 assert.equal(f.ledger.state().controls.stopRequested,true);assert.equal(f.ledger.internalShutdownRecoveryProof(knownRunIds,f.at).verified,true);assert.equal((await f.bridge.candidate(mint,true)).kind,'evaluated');assert.equal(f.ledger.state().controls.stopRequested,false);assert.equal(f.ledger.state().controls.entriesEnabled,true);assert.equal(Object.values(f.ledger.state().pending).filter(x=>x.side==='buy').length,1);
